// Fictional, server-side sample records. Never real patient data.
// Report text is written at consultant-radiologist level (structured
// headings, standard jargon) — the plain-English "Overview" is not stored
// here; it's generated by the AI from this report when the result opens.
export type Sentence = { id: string; text: string };
export type ImageKind = "ct-chest" | "mri-knee" | "mri-spine";
export type ScanRecord = {
  id: string;
  patientId: string;
  released: boolean;
  name: string;
  shortName: string;
  date: string; // ISO
  referringTeam: string;
  imageKind: ImageKind;
  report: { heading: string; sentences: Sentence[] }[];
  careNote: { author: string; date: string; patientVisible: boolean; sentences: Sentence[] } | null;
};

